/// Version der Unicode-Zeichendatenbank, aus der die Tabellen stammen.
pub const UNICODE_VERSION: (u8, u8, u8) = (18, 0, 0);

/// Allgemeine Kategorie eines Codepunkts (General_Category, UAX #44).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum GeneralCategory {
    /// `Cc`
    Control,
    /// `Cf`
    Format,
    /// `Cn`
    Unassigned,
    /// `Co`
    PrivateUse,
    /// `Cs`
    Surrogate,
    /// `Ll`
    LowercaseLetter,
    /// `Lm`
    ModifierLetter,
    /// `Lo`
    OtherLetter,
    /// `Lt`
    TitlecaseLetter,
    /// `Lu`
    UppercaseLetter,
    /// `Mc`
    SpacingMark,
    /// `Me`
    EnclosingMark,
    /// `Mn`
    NonspacingMark,
    /// `Nd`
    DecimalNumber,
    /// `Nl`
    LetterNumber,
    /// `No`
    OtherNumber,
    /// `Pc`
    ConnectorPunctuation,
    /// `Pd`
    DashPunctuation,
    /// `Pe`
    ClosePunctuation,
    /// `Pf`
    FinalPunctuation,
    /// `Pi`
    InitialPunctuation,
    /// `Po`
    OtherPunctuation,
    /// `Ps`
    OpenPunctuation,
    /// `Sc`
    CurrencySymbol,
    /// `Sk`
    ModifierSymbol,
    /// `Sm`
    MathSymbol,
    /// `So`
    OtherSymbol,
    /// `Zl`
    LineSeparator,
    /// `Zp`
    ParagraphSeparator,
    /// `Zs`
    SpaceSeparator,
}

impl GeneralCategory {
    /// Der Kurzname, etwa `Lu`.
    pub const fn short_name(self) -> &'static str {
        match self {
            G::Control => "Cc",
            G::Format => "Cf",
            G::Unassigned => "Cn",
            G::PrivateUse => "Co",
            G::Surrogate => "Cs",
            G::LowercaseLetter => "Ll",
            G::ModifierLetter => "Lm",
            G::OtherLetter => "Lo",
            G::TitlecaseLetter => "Lt",
            G::UppercaseLetter => "Lu",
            G::SpacingMark => "Mc",
            G::EnclosingMark => "Me",
            G::NonspacingMark => "Mn",
            G::DecimalNumber => "Nd",
            G::LetterNumber => "Nl",
            G::OtherNumber => "No",
            G::ConnectorPunctuation => "Pc",
            G::DashPunctuation => "Pd",
            G::ClosePunctuation => "Pe",
            G::FinalPunctuation => "Pf",
            G::InitialPunctuation => "Pi",
            G::OtherPunctuation => "Po",
            G::OpenPunctuation => "Ps",
            G::CurrencySymbol => "Sc",
            G::ModifierSymbol => "Sk",
            G::MathSymbol => "Sm",
            G::OtherSymbol => "So",
            G::LineSeparator => "Zl",
            G::ParagraphSeparator => "Zp",
            G::SpaceSeparator => "Zs",
        }
    }

    /// Der Langname, etwa `Uppercase_Letter`.
    pub const fn long_name(self) -> &'static str {
        match self {
            G::Control => "Control",
            G::Format => "Format",
            G::Unassigned => "Unassigned",
            G::PrivateUse => "Private_Use",
            G::Surrogate => "Surrogate",
            G::LowercaseLetter => "Lowercase_Letter",
            G::ModifierLetter => "Modifier_Letter",
            G::OtherLetter => "Other_Letter",
            G::TitlecaseLetter => "Titlecase_Letter",
            G::UppercaseLetter => "Uppercase_Letter",
            G::SpacingMark => "Spacing_Mark",
            G::EnclosingMark => "Enclosing_Mark",
            G::NonspacingMark => "Nonspacing_Mark",
            G::DecimalNumber => "Decimal_Number",
            G::LetterNumber => "Letter_Number",
            G::OtherNumber => "Other_Number",
            G::ConnectorPunctuation => "Connector_Punctuation",
            G::DashPunctuation => "Dash_Punctuation",
            G::ClosePunctuation => "Close_Punctuation",
            G::FinalPunctuation => "Final_Punctuation",
            G::InitialPunctuation => "Initial_Punctuation",
            G::OtherPunctuation => "Other_Punctuation",
            G::OpenPunctuation => "Open_Punctuation",
            G::CurrencySymbol => "Currency_Symbol",
            G::ModifierSymbol => "Modifier_Symbol",
            G::MathSymbol => "Math_Symbol",
            G::OtherSymbol => "Other_Symbol",
            G::LineSeparator => "Line_Separator",
            G::ParagraphSeparator => "Paragraph_Separator",
            G::SpaceSeparator => "Space_Separator",
        }
    }

    /// Gruppe `C` (Other): Cc, Cf, Cn, Co, Cs.
    pub const fn is_other(self) -> bool {
        matches!(self, G::Control | G::Format | G::Unassigned | G::PrivateUse | G::Surrogate)
    }

    /// Gruppe `L` (Letter): Ll, Lm, Lo, Lt, Lu.
    pub const fn is_letter(self) -> bool {
        matches!(self, G::LowercaseLetter | G::ModifierLetter | G::OtherLetter | G::TitlecaseLetter | G::UppercaseLetter)
    }

    /// Gruppe `LC` (Cased_Letter): Ll, Lt, Lu.
    pub const fn is_cased_letter(self) -> bool {
        matches!(self, G::LowercaseLetter | G::TitlecaseLetter | G::UppercaseLetter)
    }

    /// Gruppe `M` (Mark): Mc, Me, Mn.
    pub const fn is_mark(self) -> bool {
        matches!(self, G::SpacingMark | G::EnclosingMark | G::NonspacingMark)
    }

    /// Gruppe `N` (Number): Nd, Nl, No.
    pub const fn is_number(self) -> bool {
        matches!(self, G::DecimalNumber | G::LetterNumber | G::OtherNumber)
    }

    /// Gruppe `P` (Punctuation): Pc, Pd, Pe, Pf, Pi, Po, Ps.
    pub const fn is_punctuation(self) -> bool {
        matches!(self, G::ConnectorPunctuation | G::DashPunctuation | G::ClosePunctuation | G::FinalPunctuation | G::InitialPunctuation | G::OtherPunctuation | G::OpenPunctuation)
    }

    /// Gruppe `S` (Symbol): Sc, Sk, Sm, So.
    pub const fn is_symbol(self) -> bool {
        matches!(self, G::CurrencySymbol | G::ModifierSymbol | G::MathSymbol | G::OtherSymbol)
    }

    /// Gruppe `Z` (Separator): Zl, Zp, Zs.
    pub const fn is_separator(self) -> bool {
        matches!(self, G::LineSeparator | G::ParagraphSeparator | G::SpaceSeparator)
    }
}

