/// Wie ein Zeichen in Schriften wie Arabisch verbunden wird (Joining_Type).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum JoiningType {
    /// `C`
    JoinCausing,
    /// `D`
    DualJoining,
    /// `L`
    LeftJoining,
    /// `R`
    RightJoining,
    /// `T`
    Transparent,
    /// `U`
    NonJoining,
}

impl JoiningType {
    /// Der Kurzname, etwa `D`.
    pub const fn short_name(self) -> &'static str {
        match self {
            J::JoinCausing => "C",
            J::DualJoining => "D",
            J::LeftJoining => "L",
            J::RightJoining => "R",
            J::Transparent => "T",
            J::NonJoining => "U",
        }
    }

    /// Der Langname, etwa `Dual_Joining`.
    pub const fn long_name(self) -> &'static str {
        match self {
            J::JoinCausing => "Join_Causing",
            J::DualJoining => "Dual_Joining",
            J::LeftJoining => "Left_Joining",
            J::RightJoining => "Right_Joining",
            J::Transparent => "Transparent",
            J::NonJoining => "Non_Joining",
        }
    }
}

